      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-session-path\",\n  \"version\": \"0.1.2\",\n  \"description\": \"DeepSeek Harness plugin: copy a session's log path (and an agent-readable handoff) so another session can read it and continue the work.\",\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"session\",\n    \"session-log\",\n    \"handoff\",\n    \"path\",\n    \"会话\",\n    \"接续\"\n  ],\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/**/*.js\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/439436269-ctrl/dsh-session-path.git\"\n  },\n  \"homepage\": \"https://github.com/439436269-ctrl/dsh-session-path#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/439436269-ctrl/dsh-session-path/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"engines\": {\n    \"node\": \">=22\"\n  },\n  \"scripts\": {\n    \"test\": \"node test/selftest.mjs\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.0-rc.2\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-primitives\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\"\n      }\n    }\n  }\n}\n"
