      "content": "/**\n * Read DSH session logs.\n *\n * A committed log is either plain JSONL or a Zstandard container holding **one\n * independent frame per append batch** — the host flushes each batch as its own\n * checksummed frame. Node's `zstdDecompressSync` decodes a single frame and\n * fails on the next frame's magic, so the container must be walked frame by\n * frame. {@link scanZstdFrames} does that structurally (block payloads are\n * skipped, never inflated), which keeps memory to one frame at a time and makes\n * a partially written tail frame harmless.\n *\n * @module dsh-session-path/zstd\n */\n\nimport { open } from \"node:fs/promises\";\nimport zlib from \"node:zlib\";\n\n/** `ZSTD_MAGICNUMBER`, little-endian in the stream. */\nconst ZSTD_MAGIC = 0xfd2fb528;\n\n/** How many compressed bytes are pulled from disk per read. */\nconst READ_CHUNK_BYTES = 1 << 20;\n\n/**\n * Packed增量 rows: the host appends text/reasoning/tool-call deltas as these\n * types. They dominate a log's size and are meaningless to a reader, so parsed\n * records drop them before they can be materialised.\n */\nconst PACKED_TYPES = new Set([\"text-chunks\", \"reasoning-chunks\", \"tool-call-chunks\", \"text-delta\", \"reasoning-delta\"]);\n\n/**\n * Byte ranges of the complete Zstandard frames at the head of `buffer`.\n *\n * Parsing stops at the first byte that is not a frame start (an incomplete tail\n * frame, a corrupt region, or a skippable frame this plugin does not emit), so\n * a truncated log yields its intact prefix instead of throwing.\n *\n * @param buffer - raw container bytes.\n * @returns `{ start, end }[]` in stream order.\n */\nexport function scanZstdFrames(buffer) {\n\tconst frames = [];\n\tlet offset = 0;\n\twhile (offset < buffer.length) {\n\t\tconst start = offset;\n\t\tif (buffer.length - offset < 4) return frames;\n\t\tif (buffer.readUInt32LE(offset) !== ZSTD_MAGIC) return frames;\n\t\toffset += 4;\n\t\tif (offset === buffer.length) return frames;\n\t\tconst descriptor = buffer.readUInt8(offset);\n\t\toffset += 1;\n\t\tif ((descriptor & 24) !== 0) return frames; // reserved bits: structurally invalid\n\t\tconst contentSizeFlag = descriptor >>> 6;\n\t\tconst singleSegment = (descriptor & 32) !== 0;\n\t\tconst checksum = (descriptor & 4) !== 0;\n\t\tconst dictionaryFlag = descriptor & 3;\n\t\tconst dictionaryBytes = dictionaryFlag === 3 ? 4 : dictionaryFlag;\n\t\tconst contentSizeBytes = contentSizeFlag === 0 ? (singleSegment ? 1 : 0) : 1 << contentSizeFlag;\n\t\tconst remainingHeaderBytes = (singleSegment ? 0 : 1) + dictionaryBytes + contentSizeBytes;\n\t\tif (buffer.length - offset < remainingHeaderBytes) return frames;\n\t\toffset += remainingHeaderBytes;\n\t\tfor (;;) {\n\t\t\tif (buffer.length - offset < 3) return frames;\n\t\t\tconst blockHeader = buffer.readUIntLE(offset, 3);\n\t\t\toffset += 3;\n\t\t\tconst lastBlock = (blockHeader & 1) !== 0;\n\t\t\tconst blockType = (blockHeader >>> 1) & 3;\n\t\t\tconst blockSize = blockHeader >>> 3;\n\t\t\tif (blockType === 3) return frames; // reserved block type\n\t\t\t// An RLE block stores one byte regardless of its decompressed size.\n\t\t\tconst payloadBytes = blockType === 1 ? 1 : blockSize;\n\t\t\tif (buffer.length - offset < payloadBytes) return frames;\n\t\t\toffset += payloadBytes;\n\t\t\tif (lastBlock) break;\n\t\t}\n\t\tif (checksum) {\n\t\t\tif (buffer.length - offset < 4) return frames;\n\t\t\toffset += 4;\n\t\t}\n\t\tframes.push({ start, end: offset });\n\t}\n\treturn frames;\n}\n\n/**\n * Parse one log line, dropping blanks, packed deltas and damaged lines.\n *\n * @param line - one JSONL line.\n * @returns the record, or null when it carries no information.\n */\nexport function parseRecordLine(line) {\n\tif (line.length === 0) return null;\n\tif (line.length > 8 * 1024 * 1024) return null; // giant packed row: skip before JSON.parse\n\ttry {\n\t\tconst record = JSON.parse(line);\n\t\tif (record === null || typeof record !== \"object\") return null;\n\t\tif (PACKED_TYPES.has(record.type)) return null;\n\t\treturn record;\n\t} catch {\n\t\treturn null; // best-effort replay: one damaged line must not kill the file\n\t}\n}\n\n/**\n * Turn a text slice into records, carrying the unfinished tail line forward.\n *\n * @param text - decoded chunk.\n * @param pending - leftover from the previous chunk.\n * @returns the new pending buffer.\n */\nfunction consumeText(text, pending, out) {\n\tconst lines = text.split(\"\\n\");\n\tlines[0] = pending + lines[0];\n\tconst next = lines.pop() ?? \"\";\n\tfor (const line of lines) {\n\t\tconst record = parseRecordLine(line);\n\t\tif (record !== null) out.push(record);\n\t}\n\treturn next;\n}\n\n/**\n * Walk one session log and yield its records.\n *\n * The file is read in chunks; complete frames found at the head of the working\n * buffer are inflated and released immediately, and everything after the last\n * complete frame stays in a tail buffer for the next chunk. `maxBytes` bounds\n * the compressed bytes read, which is how callers keep a title probe cheap on a\n * multi-hundred-megabyte log.\n *\n * @param file - `session.vN.jsonl.zstd` or `session.jsonl` path.\n * @param options - `{ maxBytes?, onFrame? }`.\n * @yields parsed records in log order.\n */\nexport async function* readSessionRecords(file, options = {}) {\n\tconst maxBytes = Number(options.maxBytes) > 0 ? Number(options.maxBytes) : Infinity;\n\tconst onFrame = typeof options.onFrame === \"function\" ? options.onFrame : null;\n\tconst handle = await open(file, \"r\");\n\ttry {\n\t\tconst compressed = file.endsWith(\".zstd\");\n\t\tlet pending = \"\";\n\t\tlet tail = Buffer.alloc(0);\n\t\tlet read = 0;\n\t\tfor (;;) {\n\t\t\tconst chunk = await handle.read(Buffer.allocUnsafe(READ_CHUNK_BYTES), 0, READ_CHUNK_BYTES, null);\n\t\t\tif (chunk.bytesRead === 0) break;\n\t\t\tread += chunk.bytesRead;\n\t\t\tconst slice = chunk.buffer.subarray(0, chunk.bytesRead);\n\t\t\tconst data = tail.length > 0 ? Buffer.concat([tail, slice]) : Buffer.from(slice);\n\t\t\ttail = Buffer.alloc(0);\n\t\t\tif (!compressed) {\n\t\t\t\tconst out = [];\n\t\t\t\tpending = consumeText(data.toString(\"utf8\"), pending, out);\n\t\t\t\tif (out.length > 0) yield* out;\n\t\t\t} else {\n\t\t\t\tconst frames = scanZstdFrames(data);\n\t\t\t\tfor (const frame of frames) {\n\t\t\t\t\tconst plain = inflateFrame(data, frame);\n\t\t\t\t\tif (plain === null) return;\n\t\t\t\t\tonFrame?.(frame.end - frame.start);\n\t\t\t\t\tconst out = [];\n\t\t\t\t\tpending = consumeText(plain, pending, out);\n\t\t\t\t\tif (out.length > 0) yield* out;\n\t\t\t\t}\n\t\t\t\tconst consumed = frames.length > 0 ? frames[frames.length - 1].end : 0;\n\t\t\t\ttail = Buffer.from(data.subarray(consumed));\n\t\t\t\t// A full chunk that still yields no frame means the container is\n\t\t\t\t// damaged; stop rather than buffer the rest of the file forever.\n\t\t\t\tif (frames.length === 0 && tail.length >= READ_CHUNK_BYTES * 2) return;\n\t\t\t}\n\t\t\tif (read >= maxBytes) break;\n\t\t}\n\t\tif (!compressed && pending.length > 0) {\n\t\t\tconst record = parseRecordLine(pending);\n\t\t\tif (record !== null) yield record;\n\t\t}\n\t} finally {\n\t\tawait handle.close();\n\t}\n}\n\n/**\n * Inflate one scanned frame, or null when the bytes are damaged.\n *\n * @param data - the working buffer.\n * @param frame - `{ start, end }` from {@link scanZstdFrames}.\n * @returns decoded UTF-8 text.\n */\nfunction inflateFrame(data, frame) {\n\ttry {\n\t\treturn inflate(data.subarray(frame.start, frame.end));\n\t} catch {\n\t\treturn null;\n\t}\n}\n\n/** Decode one complete Zstandard frame (absent on exotic runtimes). */\nfunction inflate(bytes) {\n\tif (typeof zlib.zstdDecompressSync !== \"function\") throw new Error(\"zstd is unavailable on this runtime\");\n\treturn zlib.zstdDecompressSync(bytes).toString(\"utf8\");\n}\n"
    },
    {
      "path": "lib/handoff.js",
      "content": "/**\n * Turn a session log into a readable handoff file.\n *\n * The raw log is a compressed event stream: another agent can find it but cannot\n * `read` it. This module renders the parts a continuation actually needs —\n * user messages, assistant text, and the tool calls between them — and writes\n * either a Markdown transcript or the decompressed JSONL, keeping the **tail**\n * of the session when the character budget bites (the most recent turns are what\n * a continuation must see).\n *\n * @module dsh-session-path/handoff\n */\n\nimport { mkdir, writeFile } from \"node:fs/promises\";\nimport { join } from \"node:path\";\n\nimport { readSessionRecords } from \"./zstd.js\";\nimport { dshHome } from \"./paths.js\";\n\n/** Longest tool-call rendering kept per call. */\nconst TOOL_ARG_CHARS = 240;\n/** Longest single message kept verbatim. */\nconst MESSAGE_CHARS = 20_000;\n\n/**\n * Join the text blocks of one message.\n *\n * @param content - message content array.\n * @returns the concatenated text.\n */\nfunction messageText(content) {\n\tif (!Array.isArray(content)) return \"\";\n\tconst parts = [];\n\tfor (const block of content) {\n\t\tif (block === null || typeof block !== \"object\") continue;\n\t\tif (block.type !== \"text\" || typeof block.text !== \"string\") continue;\n\t\tparts.push(block.text);\n\t}\n\treturn parts.join(\"\\n\").trim();\n}\n\n/**\n * One short line for a tool call, so the transcript records what was run.\n *\n * @param record - a `tool/call` record.\n * @returns the rendered line.\n */\nfunction toolLine(record) {\n\tconst name = typeof record.data?.name === \"string\" ? record.data.name : \"tool\";\n\tconst raw = typeof record.data?.arguments === \"string\" ? record.data.arguments : \"\";\n\tconst args = raw.length > TOOL_ARG_CHARS ? `${raw.slice(0, TOOL_ARG_CHARS)}…` : raw;\n\treturn `- \\`${name}\\` ${args}`.trimEnd();\n}\n\n/**\n * Render one record as a transcript entry, or null when it is not user-visible.\n *\n * @param record - a parsed log record.\n * @returns `{ role, text }` or null.\n */\nfunction toEntry(record) {\n\tswitch (record.type) {\n\t\tcase \"user/message\": {\n\t\t\tconst text = messageText(record.data?.content);\n\t\t\tconst kind = record.data?.source?.kind;\n\t\t\tif (text === \"\") return null;\n\t\t\t// Plugin injections are host bookkeeping, not something the user said.\n\t\t\tif (typeof kind === \"string\" && kind !== \"user\") return { role: \"context\", text };\n\t\t\treturn { role: \"user\", text };\n\t\t}\n\t\tcase \"assistant/message\": {\n\t\t\tconst text = messageText(record.data?.message?.content);\n\t\t\treturn text === \"\" ? null : { role: \"assistant\", text };\n\t\t}\n\t\tcase \"tool/call\":\n\t\t\treturn { role: \"tool\", text: toolLine(record) };\n\t\tdefault:\n\t\t\treturn null;\n\t}\n}\n\n/** Markdown heading per entry role. */\nconst HEADING = { user: \"## 用户\", assistant: \"## 助手\", tool: \"## 工具调用\", context: \"## 上下文注入\" };\n\n/**\n * Render the transcript, keeping the most recent entries within `maxChars`.\n *\n * @param entries - transcript entries in log order.\n * @param maxChars - character budget for the entry bodies.\n * @returns `{ body, kept, truncated }`.\n */\nexport function renderEntries(entries, maxChars) {\n\tconst kept = [];\n\tlet used = 0;\n\tlet truncated = false;\n\tfor (let index = entries.length - 1; index >= 0; index -= 1) {\n\t\tconst entry = entries[index];\n\t\tconst text = entry.text.length > MESSAGE_CHARS ? `${entry.text.slice(0, MESSAGE_CHARS)}\\n…（本条已截断）` : entry.text;\n\t\tconst size = text.length + HEADING[entry.role].length + 4;\n\t\tif (kept.length > 0 && used + size > maxChars) {\n\t\t\ttruncated = true;\n\t\t\tbreak;\n\t\t}\n\t\tkept.push({ ...entry, text });\n\t\tused += size;\n\t}\n\tkept.reverse();\n\tconst body = kept.map((entry) => `${HEADING[entry.role]}\\n\\n${entry.text}`).join(\"\\n\\n\");\n\treturn { body, kept: kept.length, truncated };\n}\n\n/**\n * Markdown handoff: a header block plus the tail of the transcript.\n *\n * @param info - resolved session info.\n * @param entries - transcript entries.\n * @param maxChars - character budget.\n * @returns `{ text, kept, truncated }`.\n */\nexport function renderMarkdown(info, entries, maxChars) {\n\tconst { body, kept, truncated } = renderEntries(entries, maxChars);\n\tconst header = [\n\t\t\"# 会话接续记录\",\n\t\t\"\",\n\t\t`- 会话 ID：${info.sessionId}`,\n\t\t`- 标题：${info.title === \"\" ? \"(无标题)\" : info.title}`,\n\t\t`- 工作目录：${info.cwd === \"\" ? \"(未知)\" : info.cwd}`,\n\t\t`- 会话日志：${info.logPath === \"\" ? \"(未找到)\" : info.logPath}`,\n\t\t`- 导出时间：${new Date().toISOString()}`,\n\t\t`- 导出条目：${kept}${truncated ? \"（仅保留最近部分，前文已截断）\" : \"\"}`,\n\t\t\"\",\n\t\t\"---\",\n\t\t\"\",\n\t];\n\treturn { text: `${header.join(\"\\n\")}${body}\\n`, kept, truncated };\n}\n\n/**\n * JSONL handoff: one header line plus the decompressed records.\n *\n * @param info - resolved session info.\n * @param records - parsed records in log order.\n * @param maxChars - character budget.\n * @returns `{ text, kept, truncated }`.\n */\nexport function renderJsonl(info, records, maxChars) {\n\tconst header = {\n\t\ttype: \"session/handoff\",\n\t\tsessionId: info.sessionId,\n\t\ttitle: info.title,\n\t\tcwd: info.cwd,\n\t\tlogPath: info.logPath,\n\t\texportedAt: new Date().toISOString(),\n\t};\n\tconst lines = [JSON.stringify(header)];\n\tlet used = lines[0].length;\n\tlet kept = 0;\n\tfor (const record of records) {\n\t\tconst line = JSON.stringify(record);\n\t\tif (used + line.length > maxChars) break;\n\t\tlines.push(line);\n\t\tused += line.length + 1;\n\t\tkept += 1;\n\t}\n\treturn { text: `${lines.join(\"\\n\")}\\n`, kept, truncated: kept < records.length };\n}\n\n/**\n * Where handoff files live: the configured directory, else `$DSH_HOME/session-handoff`.\n *\n * @param ctx - host plugin context.\n * @param settings - resolved plugin settings.\n * @returns the absolute directory.\n */\nexport function handoffDirectory(ctx, settings) {\n\treturn settings.handoffDir !== \"\" ? settings.handoffDir : join(dshHome(ctx), \"session-handoff\");\n}\n\n/**\n * Build one handoff file for a session and return where it landed.\n *\n * @param ctx - host plugin context.\n * @param settings - resolved plugin settings.\n * @param info - resolved session info.\n * @param options - `{ format?, maxChars? }`.\n * @returns `{ file, chars, kept, truncated, format }`.\n */\nexport async function writeHandoff(ctx, settings, info, options = {}) {\n\tconst format = options.format === \"jsonl\" ? \"jsonl\" : settings.handoffFormat;\n\tconst maxChars = Number(options.maxChars) > 0 ? Math.floor(Number(options.maxChars)) : settings.maxHandoffChars;\n\tif (info.logPath === \"\") throw new Error(`no committed log found for session \"${info.sessionId}\"`);\n\tconst directory = handoffDirectory(ctx, settings);\n\tawait mkdir(directory, { recursive: true });\n\tlet text;\n\tlet kept;\n\tlet truncated;\n\tif (format === \"jsonl\") {\n\t\tconst records = [];\n\t\tfor await (const record of readSessionRecords(info.logPath)) records.push(record);\n\t\tconst rendered = renderJsonl(info, records, maxChars);\n\t\ttext = rendered.text;\n\t\tkept = rendered.kept;\n\t\ttruncated = rendered.truncated;\n\t} else {\n\t\tconst entries = [];\n\t\tfor await (const record of readSessionRecords(info.logPath)) {\n\t\t\tconst entry = toEntry(record);\n\t\t\tif (entry !== null) entries.push(entry);\n\t\t}\n\t\tconst rendered = renderMarkdown(info, entries, maxChars);\n\t\ttext = rendered.text;\n\t\tkept = rendered.kept;\n\t\ttruncated = rendered.truncated;\n\t}\n\tconst safeId = info.sessionId.replace(/[^A-Za-z0-9._-]/g, \"_\");\n\tconst file = join(directory, `${safeId}.${format === \"jsonl\" ? \"jsonl\" : \"md\"}`);\n\tawait writeFile(file, text, \"utf8\");\n\treturn { file, chars: text.length, kept, truncated, format };\n}\n"
    },
    {
      "path": "lib/session-info.js",
      "content": "/**\n * Resolve everything a caller needs to know about one session: its id, title,\n * workspace directory and the absolute path of its committed log.\n *\n * The workspace directory comes from the live session header when the session is\n * mounted, and the log path comes from an authoritative directory lookup — never\n * from a derived guess alone, so a renamed project folder cannot produce a path\n * that does not exist.\n *\n * @module dsh-session-path/session-info\n */\n\nimport { findSessionDirectory, sessionsRoot } from \"./paths.js\";\nimport { readSessionRecords } from \"./zstd.js\";\n\n/** Longest accepted session id / title / cwd hint (untrusted input from the GUI). */\nconst MAX_HINT_CHARS = 4096;\n\n/**\n * The live session header, when the host's session store has the session.\n *\n * @param ctx - host plugin context.\n * @param sessionId - session id.\n * @returns the header object, or an empty object.\n */\nexport function liveSessionHeader(ctx, sessionId) {\n\ttry {\n\t\tconst sessions = ctx?.get?.(\"sessions\");\n\t\tconst session = typeof sessions?.get === \"function\" ? sessions.get(sessionId) : undefined;\n\t\tconst header = session?.header;\n\t\treturn header !== null && typeof header === \"object\" ? header : {};\n\t} catch {\n\t\treturn {};\n\t}\n}\n\n/**\n * Normalise one untrusted string hint (or an empty string).\n *\n * @param value - candidate value.\n * @returns the trimmed value within the length cap.\n */\nfunction hint(value) {\n\treturn typeof value === \"string\" && value.length > 0 ? value.slice(0, MAX_HINT_CHARS) : \"\";\n}\n\n/**\n * The session's title from its log, taken from the last `session/title` event\n * inside a bounded prefix of the file.\n *\n * @param file - log path.\n * @param maxBytes - compressed byte budget.\n * @returns the title, or an empty string.\n */\nexport async function readSessionTitle(file, maxBytes) {\n\tlet title = \"\";\n\ttry {\n\t\tfor await (const record of readSessionRecords(file, { maxBytes })) {\n\t\t\tif (record.type !== \"session/title\") continue;\n\t\t\tconst next = record.data?.title;\n\t\t\tif (typeof next === \"string\" && next.trim().length > 0) title = next.trim();\n\t\t}\n\t} catch {\n\t\t/* the title is cosmetic: a damaged log must not fail the whole call */\n\t}\n\treturn title;\n}\n\n/**\n * The session's own header record from the log (`{ type: \"session\", cwd, ... }`).\n *\n * A cold session — one this process never mounted — has no live header, and the\n * workspace directory is what a continuation needs most. The header is the first\n * record of the first frame, so a small byte budget is always enough.\n *\n * @param file - log path.\n * @param maxBytes - compressed byte budget.\n * @returns the header record, or null.\n */\nexport async function readSessionHeader(file, maxBytes = 262_144) {\n\ttry {\n\t\tfor await (const record of readSessionRecords(file, { maxBytes })) {\n\t\t\tif (record.type === \"session\") return record;\n\t\t}\n\t} catch {\n\t\t/* fall through: an unknown cwd is reported as empty */\n\t}\n\treturn null;\n}\n\n/**\n * Everything the tools and the HTTP route need about one session.\n *\n * @param ctx - host plugin context.\n * @param settings - resolved plugin settings.\n * @param sessionId - the session to resolve.\n * @param hints - optional GUI-supplied `{ title, cwd }` (cosmetic, unverified).\n * @returns the resolved session info.\n */\nexport async function resolveSessionInfo(ctx, settings, sessionId, hints = {}) {\n\tconst id = hint(sessionId);\n\tif (id === \"\") throw new Error(\"session id is required\");\n\tconst header = liveSessionHeader(ctx, id);\n\tconst hintedCwd = hint(hints.cwd);\n\tconst liveCwd = hint(header.cwd);\n\tconst root = sessionsRoot(ctx);\n\tconst found = findSessionDirectory(root, id, liveCwd || hintedCwd);\n\tconst logs = found?.logs ?? [];\n\tconst logPath = logs[0] ?? \"\";\n\tlet cwd = liveCwd || hintedCwd;\n\tif (cwd === \"\" && logPath !== \"\") cwd = hint((await readSessionHeader(logPath))?.cwd);\n\tlet title = hint(hints.title);\n\tif (title === \"\" && logPath !== \"\") title = await readSessionTitle(logPath, settings.titleScanBytes);\n\treturn {\n\t\tsessionId: id,\n\t\ttitle,\n\t\tcwd,\n\t\tlogPath,\n\t\tdir: found?.dir ?? \"\",\n\t\tproject: found?.project ?? \"\",\n\t\troot,\n\t\texists: logPath !== \"\",\n\t};\n}\n"
    },
    {
      "path": "lib/trust.js",
      "content": "/**\n * The trust fence for this plugin's HTTP route.\n *\n * The Web GUI is served on loopback and may also be reached through a LAN bind,\n * a reverse proxy or a tunnel, so the route accepts a request only when its\n * `Host` is loopback or an explicitly trusted authority, not a cross-site fetch,\n * and — when an `Origin` is present — same-host. This mirrors the fence the\n * shipped Web routes use; a browser cannot forge these headers from another\n * origin, which is what keeps the route from becoming an open session-path oracle.\n *\n * @module dsh-session-path/trust\n */\n\n/** Case-insensitive header lookup (Node lowercases, fakes may not). */\nfunction headerOf(headers, name) {\n\tconst value = headers?.[name];\n\tif (typeof value === \"string\") return value;\n\tif (Array.isArray(value) && typeof value[0] === \"string\") return value[0];\n\treturn undefined;\n}\n\n/**\n * Hostname only, from a `Host` header value (IPv6 brackets preserved).\n *\n * @param host - the raw header value.\n * @returns the hostname, or null when unparsable.\n */\nexport function authorityHostname(host) {\n\ttry {\n\t\treturn new URL(`http://${host}`).hostname.toLowerCase();\n\t} catch {\n\t\treturn null;\n\t}\n}\n\n/**\n * Whether a hostname is a loopback spelling.\n *\n * @param hostname - lowercased hostname.\n * @returns true for localhost / 127.0.0.0-8 / ::1.\n */\nexport function isLoopbackHostname(hostname) {\n\tif (hostname === \"localhost\" || hostname === \"::1\" || hostname === \"[::1]\") return true;\n\treturn /^127(?:\\.\\d{1,3}){3}$/.test(hostname);\n}\n\n/**\n * Whether `Host` matches one of the runtime's trusted authorities.\n *\n * @param host - raw `Host` header value.\n * @param trustedHosts - authorities from the web runtime (`host` or `host:port`).\n * @returns true on an exact authority match.\n */\nexport function isTrustedAuthority(host, trustedHosts) {\n\tif (!Array.isArray(trustedHosts)) return false;\n\tconst wanted = host.toLowerCase();\n\treturn trustedHosts.some((entry) => typeof entry === \"string\" && entry.toLowerCase() === wanted);\n}\n\n/**\n * The fence itself.\n *\n * @param request - the HTTP request.\n * @param trustedHosts - authorities from the web runtime.\n * @returns true when the request may read session paths.\n */\nexport function isTrustedRequest(request, trustedHosts) {\n\tconst host = headerOf(request?.headers, \"host\");\n\tif (host === undefined) return false;\n\tconst hostname = authorityHostname(host);\n\tif (hostname === null) return false;\n\tif (!isLoopbackHostname(hostname) && !isTrustedAuthority(host, trustedHosts)) return false;\n\tif (headerOf(request?.headers, \"sec-fetch-site\") === \"cross-site\") return false;\n\tconst origin = headerOf(request?.headers, \"origin\");\n\tif (origin === undefined) return true;\n\ttry {\n\t\treturn new URL(origin).hostname.toLowerCase() === hostname;\n\t} catch {\n\t\treturn false;\n\t}\n}\n"
    },
    {
      "path": "lib/tools.js",
      "content": "/**\n * The two agent-facing tools.\n *\n * `session_path` answers \"where is this session's log?\" (no writes), and\n * `session_handoff` answers \"give me something I can actually read\" by writing a\n * decompressed transcript next to the DSH home. Together they are how one\n * session hands its context to another.\n *\n * @module dsh-session-path/tools\n */\n\nimport { composeCopyText } from \"./copy-text.js\";\nimport { writeHandoff } from \"./handoff.js\";\nimport { resolveSessionInfo } from \"./session-info.js\";\n\n/**\n * The session a call targets: the explicit argument, else the calling session.\n *\n * @param args - tool arguments.\n * @param exec - tool execution context.\n * @returns the session id.\n */\nfunction targetSessionId(args, exec) {\n\tconst explicit = typeof args?.sessionId === \"string\" ? args.sessionId.trim() : \"\";\n\tif (explicit !== \"\") return explicit;\n\tconst own = exec?.agent?.session?.id;\n\tif (typeof own === \"string\" && own !== \"\") return own;\n\tthrow new Error(\"no session id: pass sessionId, or call this from inside a session\");\n}\n\n/** Shared `sessionId` parameter description. */\nconst SESSION_ID_PARAM = {\n\ttype: \"string\",\n\tdescription: \"Session id to inspect. Omit to use the session this call runs in (`session-<uuid>` and bare-uuid spellings are both accepted).\",\n};\n\n/**\n * Build both tool specs bound to one plugin instance.\n *\n * @param options - `{ ctx, settings }`.\n * @returns tool specs consumed by the entry point.\n */\nexport function createToolSpecs({ ctx, settings }) {\n\treturn [\n\t\t{\n\t\t\tname: \"session_path\",\n\t\t\tdescription:\n\t\t\t\t\"Resolve a DSH session's on-disk log path and workspace directory. Use when the user asks to copy a session's path, to check where a session is stored, or to hand a session off to another session. Omit sessionId for the current session. Read-only: nothing is written.\",\n\t\t\tparameters: {\n\t\t\t\tsessionId: SESSION_ID_PARAM,\n\t\t\t\tformat: {\n\t\t\t\t\ttype: \"string\",\n\t\t\t\t\tdescription: 'Copy payload: \"path\" (bare log path) or \"block\" (paste-ready handoff block, default).',\n\t\t\t\t},\n\t\t\t},\n\t\t\toutputSchema: {\n\t\t\t\ttype: \"object\",\n\t\t\t\tadditionalProperties: false,\n\t\t\t\tproperties: {\n\t\t\t\t\tok: { type: \"boolean\", required: true },\n\t\t\t\t\tsessionId: { type: \"string\", required: true },\n\t\t\t\t\ttitle: { type: \"string\", required: true },\n\t\t\t\t\tcwd: { type: \"string\", required: true },\n\t\t\t\t\tlogPath: { type: \"string\", required: true },\n\t\t\t\t\tdir: { type: \"string\", required: true },\n\t\t\t\t\texists: { type: \"boolean\", required: true },\n\t\t\t\t\ttext: { type: \"string\", required: true },\n\t\t\t\t},\n\t\t\t},\n\t\t\tpresentCall: (args) => ({ card: \"generic\", title: \"session_path\", kind: \"execute\", detail: args?.sessionId ?? \"\" }),\n\t\t\trender: (_args, value) =>\n\t\t\t\tvalue.exists\n\t\t\t\t\t? [\n\t\t\t\t\t\t\t{ type: \"text\", text: `会话 ${value.sessionId} 的日志：${value.logPath}` },\n\t\t\t\t\t\t\t{ type: \"text\", text: value.text },\n\t\t\t\t\t\t]\n\t\t\t\t\t: [{ type: \"text\", text: `未找到会话 ${value.sessionId} 的日志文件（sessions 根：${value.dir === \"\" ? \"?\" : value.dir}）。` }],\n\t\t\tasync execute(args, exec) {\n\t\t\t\tconst sessionId = targetSessionId(args, exec);\n\t\t\t\tconst format = args?.format === \"path\" ? \"path\" : settings.copyFormat;\n\t\t\t\tconst info = await resolveSessionInfo(ctx, settings, sessionId, {});\n\t\t\t\treturn {\n\t\t\t\t\tok: true,\n\t\t\t\t\tsessionId: info.sessionId,\n\t\t\t\t\ttitle: info.title,\n\t\t\t\t\tcwd: info.cwd,\n\t\t\t\t\tlogPath: info.logPath,\n\t\t\t\t\tdir: info.dir,\n\t\t\t\t\texists: info.exists,\n\t\t\t\t\ttext: composeCopyText(info, format),\n\t\t\t\t};\n\t\t\t},\n\t\t},\n\t\t{\n\t\t\tname: \"session_handoff\",\n\t\t\tdescription:\n\t\t\t\t\"Write a readable, decompressed copy of a DSH session (Markdown transcript by default) and return its absolute path. Use to continue another session's work: call this, then `read` the returned file. Omit sessionId for the current session.\",\n\t\t\tparameters: {\n\t\t\t\tsessionId: SESSION_ID_PARAM,\n\t\t\t\tformat: {\n\t\t\t\t\ttype: \"string\",\n\t\t\t\t\tdescription: 'Output file: \"md\" (human/agent-readable transcript, default) or \"jsonl\" (plain decompressed event log).',\n\t\t\t\t},\n\t\t\t\tmaxChars: {\n\t\t\t\t\ttype: \"integer\",\n\t\t\t\t\tdescription: \"Character budget for the written file; the most recent part of the session is kept. Defaults to the plugin setting (200000).\",\n\t\t\t\t},\n\t\t\t},\n\t\t\toutputSchema: {\n\t\t\t\ttype: \"object\",\n\t\t\t\tadditionalProperties: false,\n\t\t\t\tproperties: {\n\t\t\t\t\tok: { type: \"boolean\", required: true },\n\t\t\t\t\tsessionId: { type: \"string\", required: true },\n\t\t\t\t\ttitle: { type: \"string\", required: true },\n\t\t\t\t\tcwd: { type: \"string\", required: true },\n\t\t\t\t\tlogPath: { type: \"string\", required: true },\n\t\t\t\t\tfile: { type: \"string\", required: true },\n\t\t\t\t\tformat: { type: \"string\", required: true },\n\t\t\t\t\tchars: { type: \"integer\", required: true },\n\t\t\t\t\tkept: { type: \"integer\", required: true },\n\t\t\t\t\ttruncated: { type: \"boolean\", required: true },\n\t\t\t\t},\n\t\t\t},\n\t\t\tpresentCall: (args) => ({ card: \"generic\", title: \"session_handoff\", kind: \"execute\", detail: args?.sessionId ?? \"\" }),\n\t\t\trender: (_args, value) => {\n\t\t\t\tconst lines = [\n\t\t\t\t\t`会话记录已写出：${value.file}`,\n\t\t\t\t\t`格式 ${value.format} · ${value.chars} 字符 · ${value.kept} 条${value.truncated ? \"（仅最近部分，前文已截断）\" : \"\"}`,\n\t\t\t\t\t`工作目录：${value.cwd === \"\" ? \"(未知)\" : value.cwd}`,\n\t\t\t\t\t`原始日志：${value.logPath}`,\n\t\t\t\t\t`下一步：用 read 读取 ${value.file} 即可接续该会话。`,\n\t\t\t\t];\n\t\t\t\treturn [{ type: \"text\", text: lines.join(\"\\n\") }];\n\t\t\t},\n\t\t\tasync execute(args, exec) {\n\t\t\t\tconst sessionId = targetSessionId(args, exec);\n\t\t\t\tconst info = await resolveSessionInfo(ctx, settings, sessionId, {});\n\t\t\t\tif (!info.exists) {\n\t\t\t\t\tthrow new Error(`no committed log found for session \"${info.sessionId}\" under ${info.root}; check the session id`);\n\t\t\t\t}\n\t\t\t\tconst format = args?.format === \"jsonl\" ? \"jsonl\" : args?.format === \"md\" ? \"md\" : settings.handoffFormat;\n\t\t\t\tconst result = await writeHandoff(ctx, settings, info, {\n\t\t\t\t\tformat,\n\t\t\t\t\tmaxChars: Number(args?.maxChars) > 0 ? Number(args.maxChars) : undefined,\n\t\t\t\t});\n\t\t\t\treturn {\n\t\t\t\t\tok: true,\n\t\t\t\t\tsessionId: info.sessionId,\n\t\t\t\t\ttitle: info.title,\n\t\t\t\t\tcwd: info.cwd,\n\t\t\t\t\tlogPath: info.logPath,\n\t\t\t\t\tfile: result.file,\n\t\t\t\t\tformat: result.format,\n\t\t\t\t\tchars: result.chars,\n\t\t\t\t\tkept: result.kept,\n\t\t\t\t\ttruncated: result.truncated,\n\t\t\t\t};\n\t\t\t},\n\t\t},\n\t];\n}\n"
    },
